<h1>Giỏ hàng</h1><?php if (!$items): ?><p>Giỏ hàng trống.</p><?php else: ?><div class="table-wrap"><table><thead><tr><th>Sách</th><th>Số lượng</th><th>Đơn giá</th></tr></thead><tbody><?php foreach ($items as $item): ?><tr><td><?= View::escape($item['book']['title']) ?></td><td><?= (int) $item['quantity'] ?></td><td><?= number_format((float) $item['book']['price'], 0, ',', '.') ?> ₫</td></tr><?php endforeach; ?></tbody></table></div><h2>Tổng: <?= number_format($total, 0, ',', '.') ?> ₫</h2><a class="button" href="<?= BASE_URL ?>/?r=orders/create">Thanh toán</a><?php endif; ?>
